mapper.update:
update Inv_Settlement_End a set a.pay_Apply_Sum=(select SUM(pay.pay_Apply) from con_pay pay where pay.con_id=a.con_id and pay.pay_State=7)
where a.sae_id in

    #{id}

mapper.select:
    select
    mn.*
    from Inv_Settlement_End mn
    where 1=1
    
        and mn.Te_Id = #{params.teId}
    
    
        and mn.P_Id=#{params.pId}
    
    
        and mn.Con_Id = #{params.conId}
    
    
        and mn.state = #{params.state}
    
    
        and mn.Sae_Cu_Af = #{params.saeCuAf}
    
    
        and mn.pay_Apply_Sum  >  mn.sae_Audit_Report
    
    
        and mn.pay_Apply_Sum  <=  mn.sae_Audit_Report
    
    
        and mn.Sae_Submission_User like concat('%',#{params.saeSubmissionUser},'%')
    
    
        and mn.Sae_Submission_Phone like concat('%',#{params.saeSubmissionPhone},'%')
    
    
        and mn.Sae_Examine_User like concat('%',#{params.saeExamineUser},'%')
    
    
        and mn.Sae_Examine_Phone like concat('%',#{params.saeExaminePhone},'%')
    
    
        and mn.sae_Con_Name like concat('%',#{params.saeConName},'%')
    
    
        and mn.sae_Project_Name like concat('%',#{params.saeProjectName},'%')
    
    
        and mn.sae_Party_A_Name like concat('%',#{params.saePartyAName},'%')
    
    
        and mn.Sae_Cost_Consult is not null
    
    
        and mn.Sae_Cost_Consult is null
    

    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Sae_Create_Time DESC

select
c1.C_Name as saeContractorName, c2.C_Name as saeSupervisorName, c3.C_Name as saeCostConsultName, con.con_Name as conName, con.con_Money_Total as conMoneyTotal, con.con_Type as conType, con.con_Code as conCode, mn.* from Inv_Settlement_End mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_Company c1 on mn.Sae_Contractor=c1.C_Id left join SYS_Company c2 on mn.Sae_Supervisor=c2.C_Id left join SYS_Company c3 on mn.Sae_Cost_Consult=c3.C_Id
${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Con_Id = #{params.conId}
and mn.state = #{params.state}
and mn.Sae_Cu_Af = #{params.saeCuAf}
and mn.Sae_Submission_User like concat('%',#{params.saeSubmissionUser},'%')
and mn.Sae_Submission_Phone like concat('%',#{params.saeSubmissionPhone},'%')
and mn.Sae_Examine_User like concat('%',#{params.saeExamineUser},'%')
and mn.Sae_Examine_Phone like concat('%',#{params.saeExaminePhone},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and mn.Sae_Cost_Consult is not null
and mn.Sae_Cost_Consult is null
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sae_Create_Time DESC
